CREATE FUNCTION public.pe_link_queue(_id uuid,_expense uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e pm_expenses; q financial_document_review_queue; BEGIN SELECT * INTO e FROM pm_expenses WHERE id=_expense FOR UPDATE; SELECT * INTO q FROM financial_document_review_queue WHERE id=_id FOR UPDATE; IF e.id IS NULL OR e.workflow_version<>2 OR q.id IS NULL OR q.entity_id IS DISTINCT FROM e.entity_id OR (e.submitted_by IS DISTINCT FROM auth.uid() AND NOT pe_finance_access(e.entity_id)) OR (q.created_by IS DISTINCT FROM auth.uid() AND NOT pe_finance_access(e.entity_id)) THEN RAISE EXCEPTION 'Forbidden'; END IF; IF q.created_expense_id IS NOT NULL OR q.source_project_expense_id IS NOT NULL AND q.source_project_expense_id<>e.id THEN RAISE EXCEPTION 'Receipt already linked'; END IF; UPDATE financial_document_review_queue SET source_project_expense_id=e.id,created_project_id=e.project_id,project_expense_context=jsonb_build_object('workflowVersion',2,'paidBy',e.payment_source_type,'collaboratorId',e.reimburse_collaborator_id,'rebillMode',e.rebill_mode) WHERE id=q.id; PERFORM pe_event(e.id,'receiptQueued',NULL,jsonb_build_object('queueId',q.id)); RETURN jsonb_build_object('id',q.id); END $$;
REVOKE ALL ON FUNCTION public.pe_link_queue(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.pe_link_queue(uuid,uuid) TO authenticated;
CREATE FUNCTION public.pe_queue_project_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE e pm_expenses; BEGIN IF NEW.source_project_expense_id IS NOT NULL THEN SELECT * INTO e FROM pm_expenses WHERE id=NEW.source_project_expense_id; IF e.workflow_version=2 AND NEW.created_project_id IS DISTINCT FROM e.project_id THEN RAISE EXCEPTION 'Receipt project must match its expense'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER pe_queue_project_guard BEFORE INSERT OR UPDATE ON public.financial_document_review_queue FOR EACH ROW EXECUTE FUNCTION public.pe_queue_project_guard();
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.pe_guard()'::regprocedure) INTO d; d:=pe_replace_once(d,' IF NEW.payment_source_type=''personal'' AND NEW.reimburse_collaborator_id IS NULL',' IF NEW.payment_source_type NOT IN (''personal'',''company_card'',''company_account'') OR NEW.original_currency !~ ''^[A-Z]{3}$'' OR coalesce(NEW.markup_pct,0)<0 THEN RAISE EXCEPTION ''Invalid expense context''; END IF; IF NEW.payment_source_type=''personal'' AND NEW.reimburse_collaborator_id IS NULL'); EXECUTE d; END $$;
CREATE FUNCTION public.pe_bank_reimbursement_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE txid uuid; BEGIN IF TG_OP='DELETE' THEN txid:=OLD.id; ELSE txid:=NEW.id; END IF; IF EXISTS(SELECT 1 FROM project_reimbursement_allocations WHERE bank_transaction_id=txid AND reversed_at IS NULL) AND (TG_OP='DELETE' OR (NEW.amount,NEW.bank_account_id,NEW.entity_id,NEW.transaction_date) IS DISTINCT FROM (OLD.amount,OLD.bank_account_id,OLD.entity_id,OLD.transaction_date)) THEN RAISE EXCEPTION 'Reverse reimbursements before changing transfer'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER pe_bank_reimbursement_guard BEFORE UPDATE OR DELETE ON public.bank_transactions FOR EACH ROW EXECUTE FUNCTION public.pe_bank_reimbursement_guard();